// ─── Scene 2: Only a fraction used (2:04–7:10 = 153 frames) ───
// Funnel visualization: many hashtags → only a few light up
const FUNNEL_TAGS = [
  "#gym", "#run", "#fit", "#diet", "#workout", "#body", "#health",
