const FractionScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const titleProgress = spring({ frame, fps, delay: 5, config: { damping: 200 } });

  // Tags appear first
  // Then most fade to dim, only ~4 stay bright
  const ACTIVE_INDICES = [2, 7, 12, 17];
  const dimProgress = interpolate(frame, [60, 90], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          paddingBottom: 180,
          gap: 80,
        }}
      >
        {/* Fraction label */}
        <div
          style={{
            fontSize: 52,
            fontWeight: 700,
            color: "rgba(255,255,255,0.5)",
            letterSpacing: "0.08em",
            textTransform: "uppercase",
            opacity: titleProgress,
            transform: `translateY(${interpolate(titleProgress, [0, 1], [30, 0])}px)`,
          }}
        >
          only a fraction get used
        </div>

        {/* Tag cloud grid */}
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            gap: 28,
            maxWidth: 1400,
            justifyContent: "center",
          }}
        >
          {FUNNEL_TAGS.map((tag, i) => {
            const tagProgress = spring({
              frame,
              fps,
              delay: 15 + i * 4,
              config: { damping: 200 },
            });
            const isActive = ACTIVE_INDICES.includes(i);
            const finalOpacity = isActive ? 1 : 0.12;
            const currentOpacity = interpolate(dimProgress, [0, 1], [1, finalOpacity]);

            return (
              <div
                key={i}
                style={{
                  fontSize: 44,
                  fontWeight: 700,
                  color: isActive ? COLORS.pink : "rgba(255,255,255,0.7)",
                  opacity: interpolate(tagProgress, [0, 1], [0, 1]) * currentOpacity,
                  transform: `translateY(${interpolate(tagProgress, [0, 1], [20, 0])}px)`,
                  backgroundColor: isActive
                    ? "rgba(255,100,184,0.12)"
                    : "rgba(255,255,255,0.04)",
                  border: `2px solid ${
                    isActive ? COLORS.pink : "rgba(255,255,255,0.08)"
                  }`,
                  borderRadius: 20,
                  padding: "16px 32px",
                  transition: "none",
                }}
              >
                {tag}
              </div>
            );
          })}
        </div>

        {/* Fraction indicator */}
        <div
          style={{
            opacity: interpolate(frame, [90, 115], [0, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }),
            transform: `translateY(${interpolate(
              interpolate(frame, [90, 115], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }),
              [0, 1],
              [30, 0]
            )}px)`,
            display: "flex",
            alignItems: "center",
            gap: 24,
