// ─── Scene 4: One by one search (13:19–17:12 = 92 frames) ───
// Sequential search animation, one tag at a time
const OneByOneScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const searches = ["#run", "#running", "#runner", "#runningmotivation", "#runnersofinstagram"];

  // Each search appears and then types
  const activeSearch = Math.min(Math.floor(frame / 16), searches.length - 1);
  const searchProgress = spring({
    frame,
    fps,
    delay: 0,
    config: { damping: 200 },
  });

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          paddingBottom: 180,
          gap: 40,
        }}
      >
        {/* Label */}
        <div
          style={{
            fontSize: 44,
            fontWeight: 600,
            color: "rgba(255,255,255,0.4)",
            letterSpacing: "0.06em",
            opacity: searchProgress,
            marginBottom: 20,
          }}
        >
          searching one by one...
        </div>

        {/* Search history */}
        <div style={{ width: 900, display: "flex", flexDirection: "column", gap: 20 }}>
          {searches.map((tag, i) => {
            const appeared = frame >= i * 16;
            const itemProgress = appeared
              ? spring({
                  frame: frame - i * 16,
                  fps,
                  delay: 0,
                  config: { damping: 200 },
                })
              : 0;
            const isActive = i === activeSearch;

            return (
              <div
                key={i}
                style={{
                  backgroundColor: isActive
                    ? "rgba(255,100,184,0.08)"
                    : "rgba(255,255,255,0.03)",
                  border: `2px solid ${
                    isActive ? COLORS.pink : "rgba(255,255,255,0.06)"
                  }`,
                  borderRadius: 20,
                  padding: "24px 40px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  opacity: itemProgress,
                  transform: `translateX(${interpolate(itemProgress, [0, 1], [60, 0])}px)`,
                }}
              >
                <span
                  style={{
                    fontSize: 44,
                    fontWeight: 700,
                    color: isActive ? COLORS.pink : "rgba(255,255,255,0.5)",
                  }}
                >
                  {tag}
                </span>
                {!isActive && (
                  <svg width="36" height="36" viewBox="0 0 24 24" fill="none">
                    <path
                      d="M20 6L9 17l-5-5"
                      stroke="rgba(255,255,255,0.2)"
                      strokeWidth="2.5"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                )}
                {isActive && (
                  <div
                    style={{
                      width: 32,
                      height: 32,
                      borderRadius: "50%",
                      border: `3px solid ${COLORS.pink}`,
                      borderTopColor: "transparent",
                      animation: "none",
                      transform: `rotate(${interpolate(frame, [0, 100], [0, 720])}deg)`,
                    }}
                  />
                )}
              </div>
            );
          })}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

